import React from 'react';
import BlogDetailsText from '../../../../components/blog/BlogDetailsText';

const videoSrcs=[
    'https://www.youtube.com/embed/FsXkvjiz6Zw',
    'https://www.youtube.com/embed/-QXbe7ZYRJw',
    'https://www.youtube.com/embed/tEoY6Uf--LI',
    'https://www.youtube.com/embed/Hi6LX5KwR3w',
    'https://www.youtube.com/embed/rY_u-1iK2x0',
    'https://www.youtube.com/embed/9OMn3OmLrPA',
    'https://www.youtube.com/embed/J-Zv0ccsxKo',
    'https://www.youtube.com/embed/fA_hIMN0O0E'
]

const BlogPost_EN_3 = ({ data }) => (
    <div>
        <div className='row g-4 my-5'>
            {videoSrcs.map((videoSrc,index)=>
                <div key={index} className='col-12 col-md-6 col-lg-4'>
                    <div className='ratio' style={{ '--bs-aspect-ratio': '177.78%' }}>
                        <iframe src={videoSrc} title="CNC Calibration" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>
                    </div>
                </div>
            )}
        </div>
        <BlogDetailsText data={data.excerpt} />
    </div>
)

export default BlogPost_EN_3
