import React from 'react';
import PropTypes from "prop-types";

const BlogDetailsText = ({ data }) => {
    return (
        data?.length > 1 ?
            <ul style={{ listStyle: 'disc' }}>
                {data.map((item, index) => (
                    <li key={index}>
                        <p style={{ marginBottom: '3px' }}>{item}</p>
                    </li>
                ))}
            </ul>
            :
            <p style={{ marginBottom: '3px' }}>{data?.[0]}</p>
        
    )
}
BlogDetailsText.propTypes = {
    data: PropTypes.array
};
export default BlogDetailsText;
